// Author: MiYu. Execute explicit ordered player commands against live session permissions and state.
#include "player_commands.h"
#include "session.h"
#include <bit>
#include <cmath>

namespace war3 {
unsigned dispatchPlayerCommand(ScriptSession& session,const PlayerCommand& command) {
    if(command.player>=16)return 0;bool hasPoint=command.kind==PlayerCommandKind::GroundMove || command.kind==PlayerCommandKind::GroundAttack || command.kind==PlayerCommandKind::GroundPatrol || command.kind==PlayerCommandKind::SpellPoint || command.kind==PlayerCommandKind::BuildAt;bool spell=command.kind==PlayerCommandKind::SpellUnit || command.kind==PlayerCommandKind::SpellPoint || command.kind==PlayerCommandKind::SpellImmediate;bool production=command.kind==PlayerCommandKind::Train || command.kind==PlayerCommandKind::Research || command.kind==PlayerCommandKind::Upgrade || command.kind==PlayerCommandKind::CancelUpgrade || command.kind==PlayerCommandKind::CancelBuild || command.kind==PlayerCommandKind::CancelProduction || command.kind==PlayerCommandKind::Revive || command.kind==PlayerCommandKind::ReturnResources || command.kind==PlayerCommandKind::LearnSkill;if(!hasPoint && !spell && !production && command.kind!=PlayerCommandKind::Stop && command.kind!=PlayerCommandKind::Hold && command.kind!=PlayerCommandKind::TargetOrder)return 0;if(hasPoint && (!std::isfinite(std::bit_cast<float>(command.xBits)) || !std::isfinite(std::bit_cast<float>(command.yBits))))return 0;if((command.kind==PlayerCommandKind::TargetOrder && (!command.target || !command.order)) || (command.kind==PlayerCommandKind::SpellUnit && !command.target) || (spell && !command.ability) || ((command.kind==PlayerCommandKind::BuildAt || command.kind==PlayerCommandKind::Train || command.kind==PlayerCommandKind::Research || command.kind==PlayerCommandKind::Upgrade || command.kind==PlayerCommandKind::Revive || command.kind==PlayerCommandKind::LearnSkill) && !command.objectType))return 0;WorldPoint point{jass::Real::fromBits(command.xBits),jass::Real::fromBits(command.yBits)};unsigned accepted=0;
    for(auto id:command.units){auto found=session.units().find(id);if(found==session.units().end() || !session.canControlUnit(command.player,*found->second))continue;auto unit=found->second;bool issued=false;switch(command.kind){case PlayerCommandKind::GroundMove:issued=unit->stationaryBuilding()?session.setRally(id,point):session.moveUnit(id,point);break;case PlayerCommandKind::GroundAttack:issued=session.attackMove(id,point);break;case PlayerCommandKind::GroundPatrol:issued=session.attackMove(id,point,true);break;case PlayerCommandKind::Stop:issued=session.stopUnit(id);break;case PlayerCommandKind::Hold:issued=session.stopUnit(id,true);break;case PlayerCommandKind::TargetOrder:issued=session.targetOrder(id,command.target,command.order);break;case PlayerCommandKind::SpellUnit:issued=session.castSpell(id,command.ability,command.target);break;case PlayerCommandKind::SpellPoint:issued=session.castSpellAt(id,command.ability,point);break;case PlayerCommandKind::SpellImmediate:issued=session.castSpell(id,command.ability);break;case PlayerCommandKind::BuildAt:issued=session.build(id,command.objectType,point);break;case PlayerCommandKind::Train:issued=session.train(id,command.objectType);break;case PlayerCommandKind::Research:issued=session.research(id,command.objectType);break;case PlayerCommandKind::Upgrade:issued=session.upgradeBuilding(id,command.objectType);break;case PlayerCommandKind::CancelUpgrade:issued=session.cancelBuildingUpgrade(id);break;case PlayerCommandKind::CancelBuild:issued=session.cancelConstruction(id);break;case PlayerCommandKind::CancelProduction:issued=session.cancelProduction(id,command.queueIndex);break;case PlayerCommandKind::Revive:issued=session.queueRevival(id,command.objectType);break;case PlayerCommandKind::ReturnResources:issued=session.returnResources(id);break;case PlayerCommandKind::LearnSkill:issued=session.canManageUnitInventory(command.player,*unit) && session.learnHeroSkill(id,command.objectType);break;}if(issued){++accepted;if(command.stopOnSuccess)break;}}return accepted;
}
}
